// FELEMAYE — Home Desk Studio (Framer code component) · MONOLITH
// ONE file holds the whole desk: Alvin self-healing cutting mat, post-it, composition notebook ("COMPOSITION / SURFACE ARCHIVE"),
// Perspectives notebook, Client Suite folders, studio iPod (dark titanium, Spotify drawer, drives the site-wide audio engine) and the live matrix sheet.
// Under 980px the sheet leads and the desk objects become a tappable, text-free object tray (aria-labels only).
// @framerSupportedLayoutWidth any
// @framerSupportedLayoutHeight auto
// FRAMER: set this component's Height to "Auto" (Fit) so the footer never cuts the desk off.
// AUDIO: the iPod click wheel dispatches the "fy-audio" event consumed by FELEMAYE_AudioContext.tsx (one copy in the site layout).
// Palette: canvas #0B0B0C · cards #141416 · borders #222226 · accent #D4A373.
// Fonts: add "Caveat" (handwriting) to Framer's site fonts; it falls back gracefully if absent.
import * as React from "react"
import { addPropertyControls, ControlType } from "framer"

const LOGO = "data:image/png;base64,"
const LOGO_Y = "data:image/png;base64," // yellow relief version for the mat

type Props = {
    portalHref: string
    practiceHref: string
    calendarHref: string
    aboutHref: string
    surfaceHref: string
    writingHref: string
    capabilitiesHref: string
    polaroidSrc: string
    polaroidNote: string
    logoSrc: string
    speed: number
    showHub: boolean
    playlist: string
    showCaptions: boolean
    style?: React.CSSProperties
}

/* ───────── ecosystem data ───────── */
