const NODE_COL: Record<string, string> = { spatial: "#6E2B2B", surface: "#8C6420", procure: "#55603F", bim: "#3F5A6B", strategy: "#5B3A55", curation: "#7A4A2E", rdl: "#3A3631", people: "#2F6B63", media: "#8A4B3F" }
