function Calendar({ now }: { now: Date }) {
    const y = now.getFullYear(), m = now.getMonth(), first = new Date(y, m, 1).getDay(), dim = new Date(y, m + 1, 0).getDate()
    const cells: JSX.Element[] = []
    for (let d = 1; d <= dim; d++) {
        const idx = first + d - 1, col = idx % 7, row = Math.floor(idx / 7), cx = 18 + col * 30, cy = 92 + row * 24
        cells.push(<text key={d} x={cx} y={cy} textAnchor="middle" fontFamily="system-ui,sans-serif" fontSize="11" fill={col === 0 || col === 6 ? "#9a9a96" : INK}>{d}</text>)
        if (d === now.getDate()) cells.push(<ellipse key="today" cx={cx} cy={cy - 4} rx="13" ry="10" fill="none" stroke="#c4372b" strokeWidth="1.6" transform={`rotate(-6 ${cx} ${cy})`} />)
    }
    return (
        <g filter="url(#dc-sh)">
            <rect x="0" y="12" width="232" height="210" fill="url(#g-paper)" stroke="#d9d7cc" strokeWidth=".8" />
            <rect x="0" y="12" width="232" height="34" fill={INK} />
            <text x="116" y="36" textAnchor="middle" fontFamily="'Cormorant Garamond',Georgia,serif" fontSize="19" fill="#f4efe4" letterSpacing="3">{now.toLocaleDateString(undefined, { month: "long", year: "numeric" }).toUpperCase()}</text>
            {["S", "M", "T", "W", "T", "F", "S"].map((d, i) => <text key={i} x={18 + i * 30} y="62" textAnchor="middle" fontFamily={MONO} fontSize="8" fill="#8a8372">{d}</text>)}
            {cells}
            <text x="116" y="212" textAnchor="middle" fontFamily={HAND} fontSize="17" fill="#1f3f7a">book a studio call ↗</text>
            {Array.from({ length: 11 }).map((_, i) => <g key={i}><rect x={14 + i * 20} y="4" width="4" height="16" rx="2" fill="#9a9a96" /><rect x={14.6 + i * 20} y="4" width="1.4" height="16" fill="#fff" opacity=".7" /></g>)}
        </g>
    )
}

