/* ───────── the sheet: graph paper, border, title block, live matrix ───────── */
function Sheet({ hub, w, h, fs, nodes, hot, setHot, sel, setSel, t, coarse, logo, pausedRef }: any) {
    const tb = Math.round(h * 0.115), inset = 12
    const mx = inset + 6, my = inset + 6, mw = w - 2 * (inset + 6), mh = h - tb - 2 * (inset + 6) + 4
    const cx = mx + mw / 2 + (fs > 1 ? 0 : 40), cy = my + mh / 2 + 6
    const RO = fs > 1 ? Math.min(mw * 0.335, mh / 2 - 66) : Math.min(mw * 0.35, mh / 2 - 40), RI = RO * (fs > 1 ? 0.52 : 0.5)
    const idx: Record<string, number> = {}; nodes.forEach((n: Node, i: number) => (idx[n.id] = i))
    const inner = nodes.filter((n: Node) => n.ring === "in"), outer = nodes.filter((n: Node) => n.ring === "out")
    const pos: Record<string, { x: number; y: number; a: number }> = {}
    inner.forEach((n: Node, i: number) => { const a = (i / inner.length) * Math.PI * 2 + t * 0.09 - 0.6; pos[n.id] = { x: cx + Math.cos(a) * RI, y: cy + Math.sin(a) * RI, a } })
    outer.forEach((n: Node, i: number) => { const a = (i / outer.length) * Math.PI * 2 - t * 0.055 - 1.2; pos[n.id] = { x: cx + Math.cos(a) * RO, y: cy + Math.sin(a) * RO, a } })
    const act = hot ?? sel
    const related = new Set<string>(); if (act) { related.add(act); EDGES.forEach(([a, b]) => { if (a === act) related.add(b); if (b === act) related.add(a) }) }
    const r = fs > 1 ? 33 : 36
    const grid: JSX.Element[] = []
    for (let x = 0; x <= w; x += 10) grid.push(<line key={"x" + x} x1={x} x2={x} y1="0" y2={h} stroke={x % 50 === 0 ? "#7fa6c4" : "#bcd3e4"} strokeWidth={x % 50 === 0 ? 0.7 : 0.4} opacity={x % 50 === 0 ? 0.55 : 0.6} />)
    for (let y = 0; y <= h; y += 10) grid.push(<line key={"y" + y} x1="0" x2={w} y1={y} y2={y} stroke={y % 50 === 0 ? "#7fa6c4" : "#bcd3e4"} strokeWidth={y % 50 === 0 ? 0.7 : 0.4} opacity={y % 50 === 0 ? 0.55 : 0.6} />)
    const ticks: JSX.Element[] = []
    for (let d = 0; d < 360; d += 5) { const a = (d * Math.PI) / 180, l = d % 30 === 0 ? 9 : 4; ticks.push(<line key={d} x1={cx + Math.cos(a) * (RO + 34 * fs)} y1={cy + Math.sin(a) * (RO + 34 * fs)} x2={cx + Math.cos(a) * (RO + 34 * fs + l * fs)} y2={cy + Math.sin(a) * (RO + 34 * fs + l * fs)} stroke={INK} strokeWidth=".5" opacity=".45" />) }
    const cell = (x: number, wd: number, label: string, val: string, big?: boolean) => (
        <g key={label}><rect x={x} y={h - tb - inset + 0} width={wd} height={tb} fill="none" stroke={INK} strokeWidth=".8" />
            <text x={x + 6} y={h - tb - inset + 11 * fs} fontFamily={MONO} fontSize={6 * Math.min(fs, 1.2)} letterSpacing=".9" fill="#6d6657">{label}</text>
            <text x={x + 6} y={h - tb - inset + (big ? 28 : 27) * fs} fontFamily="'Cormorant Garamond',Georgia,serif" fontSize={(big ? 16 : 14) * Math.min(fs, 0.85)} fill={INK}>{val}</text></g>
    )
    const bx = inset, bw = w - inset * 2
    const c1 = bw * 0.2, c2 = bw * 0.41, c3 = bw * 0.11, c4 = bw * 0.1, c5 = bw * 0.1
    const today = new Date().toLocaleDateString(undefined, { year: "numeric", month: "2-digit", day: "2-digit" })
    return (
        <g>
            <rect x="0" y="0" width={w} height={h} fill="#fbfbf6" />
            {grid}
            <rect x="0" y="0" width={w} height={h} fill="url(#g-paper)" opacity=".25" />
            <rect x={inset} y={inset} width={w - inset * 2} height={h - inset * 2} fill="none" stroke={INK} strokeWidth="1.6" />
            <rect x={inset + 4} y={inset + 4} width={w - inset * 2 - 8} height={h - inset * 2 - 8} fill="none" stroke={INK} strokeWidth=".5" />
            {/* matrix */}
            <g>
                {ticks}
                <circle cx={cx} cy={cy} r={RO} fill="none" stroke={INK} strokeWidth=".6" strokeDasharray="2 4" opacity=".5" />
                <circle cx={cx} cy={cy} r={RI} fill="none" stroke={INK} strokeWidth=".6" strokeDasharray="2 4" opacity=".5" />
                <line x1={cx - RO - 14} x2={cx + RO + 14} y1={cy} y2={cy} stroke={INK} strokeWidth=".4" opacity=".35" strokeDasharray="10 3 2 3" />
                <line y1={cy - RO - 14} y2={cy + RO + 14} x1={cx} x2={cx} stroke={INK} strokeWidth=".4" opacity=".35" strokeDasharray="10 3 2 3" />
                {EDGES.map(([a, b, lab], i) => {
                    const p = pos[a], q = pos[b], on = act && (a === act || b === act)
                    const mxp = (p.x + q.x) / 2 + (cx - (p.x + q.x) / 2) * 0.28, myp = (p.y + q.y) / 2 + (cy - (p.y + q.y) / 2) * 0.28
                    const lx = 0.25 * p.x + 0.5 * mxp + 0.25 * q.x, ly = 0.25 * p.y + 0.5 * myp + 0.25 * q.y
                    return (
                        <g key={i} style={{ transition: "opacity .25s" }} opacity={act ? (on ? 1 : 0.07) : 0.5}>
                            <path d={`M${p.x},${p.y} Q${mxp},${myp} ${q.x},${q.y}`} fill="none" stroke={on ? ACCENT : INK} strokeWidth={on ? 1.7 : 0.7} strokeDasharray={on ? "" : nodes[idx[a]].ring === nodes[idx[b]].ring && nodes[idx[a]].ring === "out" ? "3 3" : ""} />
                            {on && <g><rect x={lx - (lab.length * 3.1 * fs) / 1.0 - 2} y={ly - 8 * fs} width={lab.length * 6.2 * fs + 4} height={14 * fs} fill="#fbfbf6" opacity=".92" /><text x={lx} y={ly + 3 * fs} textAnchor="middle" fontFamily={MONO} fontSize={8.6 * fs} fill={ACCENT} letterSpacing=".4">{lab}</text></g>}
                        </g>
                    )
                })}
                {hub && (<g>
                <circle cx={cx} cy={cy} r={(fs > 1 ? 38 : 40)} fill="#fbfbf6" stroke={INK} strokeWidth="1" />
                <line x1={cx - 40} x2={cx + 40} y1={cy} y2={cy} stroke={INK} strokeWidth=".4" /><line y1={cy - 40} y2={cy + 40} x1={cx} x2={cx} stroke={INK} strokeWidth=".4" />
                <circle cx={cx} cy={cy} r={(fs > 1 ? 38 : 40) - 5} fill="#fbfbf6" />
                <text x={cx} y={cy - 2} textAnchor="middle" fontFamily="'Cormorant Garamond',Georgia,serif" fontSize={fs > 1 ? 14 : 13} fill={INK} letterSpacing="1">FELEMAYE</text>
                <text x={cx} y={cy + 11} textAnchor="middle" fontFamily={MONO} fontSize={fs > 1 ? 7.5 : 6} letterSpacing="1.2" fill="#6d6657">ONE PRACTICE</text>
                </g>)}
                {nodes.map((n: Node, i: number) => {
                    const p = pos[n.id], on = !act || related.has(n.id), lw = (fs > 1 ? n.short : n.label).length * 6.4 * (fs > 1 ? 1.45 : 1), sd = Math.cos(p.a) >= 0 && p.x + r + 8 + lw < w - inset - 10 || (Math.cos(p.a) < 0 && p.x - r - 8 - lw < inset + 10)
                    const lr = r + 7
                    return (
                        <a key={n.id} href={n.href} aria-label={`${n.label}. ${n.desc}`}
                            onMouseEnter={() => setHot(n.id)} onMouseLeave={() => setHot(null)} onFocus={() => setHot(n.id)} onBlur={() => setHot(null)}
                            onClick={(e) => { if (coarse && sel !== n.id) { e.preventDefault(); setSel(n.id) } }} style={{ cursor: "pointer", outline: "none" }}>
                            <g opacity={on ? 1 : 0.22} style={{ transition: "opacity .25s" }}>
                                <circle cx={p.x} cy={p.y} r={r + 6} fill="transparent" />
                                <circle cx={p.x} cy={p.y} r={r} fill={NODE_COL[n.id] || INK} stroke={act === n.id ? GOLD : "#fbfbf6"} strokeWidth={act === n.id ? 3 : 1.5} />
                                <text x={p.x} y={p.y + (fs > 1 ? 4.2 : 4.8) * fs} textAnchor="middle" fontFamily={MONO} fontSize={(fs > 1 ? 11 : 13) * fs} fontWeight="700" fill="#fbfbf6">{n.code}</text>
                                <text x={fs > 1 ? p.x : p.x + (sd ? lr : -lr)} y={fs > 1 ? p.y + r + 15 : p.y + 3.6 * fs} textAnchor={fs > 1 ? "middle" : sd ? "start" : "end"} fontFamily={MONO} fontSize={(fs > 1 ? 8 : 9.2) * (fs > 1 ? 1.45 : 1)} letterSpacing=".7" fill={INK} stroke="#fbfbf6" strokeWidth="3" paintOrder="stroke" style={{ pointerEvents: "none" }}>{fs > 1 ? n.short : n.label}</text>
                            </g>
                        </a>
                    )
                })}
            </g>
            {/* drawing notes */}
            <g fontFamily={MONO} fill={INK} style={{ pointerEvents: "none" }}>
                {fs <= 1 && <text x={mx + 4} y={my + 14} fontSize={7.4} letterSpacing="1.4" fontWeight="700">GENERAL NOTES</text>}
                {["1. HOVER OR TAP A DISCIPLINE", "    TO TRACE ITS RELATIONSHIPS.", "2. RINGS COUNTER-ROTATE; EVERY", "    PASS CHANGES THE ADJACENCIES.", "3. INNER RING: CORE DELIVERY.", "    OUTER RING: EXTENDED PRACTICE."].slice(0, fs > 1 ? 0 : 6).map((l, i) => <text key={i} x={mx + 4} y={my + (28 + i * 11) * fs} fontSize={6.6 * fs} letterSpacing=".6" opacity=".8">{l}</text>)}
            </g>
            {/* title block */}
            <g>
                <rect x={bx} y={h - tb - inset} width={bw} height={tb} fill="#fbfbf6" stroke={INK} strokeWidth="1.4" />
                <g transform={`translate(${bx + 6} ${h - tb - inset + 5}) scale(${(tb - 10) / 226})`}><use href="#dc-logo" /></g>
                {cell(bx + tb * 0.9, c2, "DRAWING TITLE", "Transdisciplinary Ecosystem Matrix", true)}
                {cell(bx + tb * 0.9 + c2, c3, "DRAWN", "F.Y.")}
                {cell(bx + tb * 0.9 + c2 + c3, c4, "SHEET", "T-001")}
                {cell(bx + tb * 0.9 + c2 + c3 + c4, c5, "SCALE", "NTS")}
                {cell(bx + tb * 0.9 + c2 + c3 + c4 + c5, bw - (tb * 0.9 + c2 + c3 + c4 + c5), "ISSUED", today)}
            </g>
        </g>
    )
}

/* ───────── scene ───────── */
const DEFAULTS: Props = {
    portalHref: "/client-suite",
    practiceHref: "/practice",
    calendarHref: "mailto:felema@felemaye.com?subject=Studio%20call%20request",
    aboutHref: "/about",
    surfaceHref: "/surface-library",
    writingHref: "/perspectives",
    capabilitiesHref: "/capabilities",
    polaroidSrc: "",
    polaroidNote: "the courtyard at golden hour, Los Angeles",
    logoSrc: "",
    speed: 1,
    showHub: false,
    playlist: "",
    showCaptions: true,
}
export default function HomeDeskStudio(props: Props) {
    // Explicit merge so blank or missing sidebar fields fall back to the defaults above (works with or without defaultProps).
    const p: Props = { ...DEFAULTS, ...Object.fromEntries(Object.entries(props).filter(([k, v]) => v !== undefined && v !== null && (v !== "" || k === "polaroidSrc" || k === "logoSrc"))) } as Props
    const wrap = React.useRef<HTMLDivElement>(null)
    const [W, setW] = React.useState(1200)
    const [t, setT] = React.useState(0)
    const [hot, setHot] = React.useState<string | null>(null)
    const [sel, setSel] = React.useState<string | null>(null)
    const [coarse, setCoarse] = React.useState(false)
    const [open, setOpen] = React.useState(false)
    const [ipodHover, setIpodHover] = React.useState(false)
    const [st, setSt] = React.useState({ playing: false, title: "" })
    const [spLoaded, setSpLoaded] = React.useState(false)
    const [visible, setVisible] = React.useState(true)
    const paused = React.useRef(false)
    const nodes = React.useMemo(() => NODES(p), [p.capabilitiesHref, p.surfaceHref, p.writingHref])
    const logo = p.logoSrc || LOGO
    const now = React.useMemo(() => new Date(), [])
    React.useEffect(() => {
        if (!wrap.current) return
        const ro = new ResizeObserver((e) => setW(e[0].contentRect.width)); ro.observe(wrap.current)
        const io = new IntersectionObserver((e) => setVisible(e[0].isIntersecting)); io.observe(wrap.current)
        try { setCoarse(window.matchMedia("(pointer: coarse)").matches) } catch {}
        return () => { ro.disconnect(); io.disconnect() }
    }, [])
    React.useEffect(() => {
        const on = (e: any) => setSt({ playing: !!e.detail?.playing, title: e.detail?.title || "" })
        const esc = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false) }
        window.addEventListener("fy-audio-state", on); window.addEventListener("keydown", esc)
        return () => { window.removeEventListener("fy-audio-state", on); window.removeEventListener("keydown", esc) }
    }, [])
    React.useEffect(() => { if (open) setSpLoaded(true) }, [open])
    paused.current = !!hot
    React.useEffect(() => {
        let reduce = false; try { reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches } catch {}
        if (reduce || !visible) return
        let raf = 0, last = performance.now()
        const loop = (n: number) => { const dt = (n - last) / 1000; last = n; if (!paused.current && !document.hidden) setT((x) => x + dt * (p.speed || 1)); raf = requestAnimationFrame(loop) }
        raf = requestAnimationFrame(loop); return () => cancelAnimationFrame(raf)
    }, [visible, p.speed])
    const mobile = W < 980
    const selNode = nodes.find((n) => n.id === (hot ?? sel))
    const rel = selNode ? EDGES.filter(([a, b]) => a === selNode.id || b === selNode.id).map(([a, b, l]) => ({ other: nodes.find((n) => n.id === (a === selNode.id ? b : a))!, l })) : []

    const css = `
    .dc{position:relative;width:100%;font-family:system-ui,sans-serif;color:${INK};-webkit-tap-highlight-color:transparent}
    .dc a{outline:none;cursor:pointer}
    .dc a .lift{transition:transform .28s cubic-bezier(.2,.7,.2,1);transform-box:fill-box}
    .dc a:hover .lift,.dc a:focus-visible .lift{transform:translateY(-6px)}
    .dc a:focus-visible .ring{stroke:${GOLD};stroke-width:3}
    .dc a .ring{fill:transparent;stroke:transparent}
    .dc a:hover .ring{stroke:rgba(201,162,75,.55);stroke-width:2;stroke-dasharray:6 5}
    .dc .tile{box-sizing:border-box;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;text-decoration:none;color:inherit;background:rgba(18,18,18,.6);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:14px 10px 12px;min-height:44px;transition:border-color .2s,transform .2s;font:inherit;cursor:pointer;width:100%}
    .dc .tile .cap{font:italic 400 15px/1.1 'Cormorant Garamond',Georgia,serif;letter-spacing:.04em;color:#EDE6D8;text-align:center}
    .dc .tile:hover{border-color:#D4A373}
    .dc .tile:focus-visible{outline:2px solid ${GOLD};outline-offset:2px}
    .dc .mono{font:10px ${MONO};letter-spacing:.2em;text-transform:uppercase;opacity:.7}
    .dc .ipod{transition:transform .25s cubic-bezier(.2,.7,.2,1);transform-box:fill-box;transform-origin:center;cursor:pointer}
    .dc .ipod:hover,.dc .ipod:focus-within{transform:scale(1.05)}
    @media(prefers-reduced-motion:reduce){.dc a .lift,.dc .ipod{transition:none}}
    `
    const itemLink = (href: string, label: string, bx: number, by: number, bw: number, bh: number, body: React.ReactNode, tx: string) => (
        <g transform={tx}><a href={href} aria-label={label}><g className="lift">{body}</g><rect className="ring" x={bx} y={by} width={bw} height={bh} rx="4" /></a></g>
    )
    const decor = (body: React.ReactNode, tx: string) => <g transform={tx} aria-hidden="true">{body}</g>

    const polaroid = <Polaroid src={p.polaroidSrc} note={p.polaroidNote} />
    const tiles: { href: string; title: string; cap?: string; sub: string; vb: string; node: React.ReactNode }[] = [
        { href: p.portalHref, title: "Client Suite", cap: "The Private Suite", sub: "Sign in to your private project workspace", vb: "-4 -26 232 232", node: <Folders /> },
        { href: p.practiceHref, title: "B2C & B2B", cap: "Who We Serve", sub: "Who we work with, and how each practice runs", vb: "-6 -4 204 214", node: <Postit /> },
        { href: p.calendarHref, title: "Book a studio call", cap: "By Appointment", sub: "Request time with Felema", vb: "-6 0 244 232", node: <Calendar now={now} /> },
        { href: p.aboutHref, title: "The studio", cap: "The Studio", sub: "Who is behind FELEMAYE", vb: "-12 -14 254 304", node: polaroid },
        { href: p.surfaceHref, title: "Surface Library", cap: "The Surface Archive", sub: "Wallcoverings, carpets, textiles", vb: "-6 -4 182 234", node: <CompBook /> },
        { href: p.writingHref, title: "Perspectives", cap: "Perspective(s)", sub: "Essays, panels and records", vb: "-6 -4 172 236", node: <BlackBook /> },
        { href: "#ipod", title: "See what's playing in the studio", cap: "In the Studio", sub: "", vb: "-64 -6 140 200", node: <IPod st={st} onOpen={() => setOpen(true)} /> },
        { href: p.capabilitiesHref, title: "Capabilities matrix", cap: "The Practice Index", sub: "Everything the practice does", vb: "-4 -4 428 52", node: <Ruler /> },
    ]

    return (
        <div ref={wrap} className="dc" style={p.style}>
            <style>{css}</style>
            <Defs logo={logo} />
            {!mobile ? (
                <svg viewBox="0 0 1600 1000" width="100%" role="group" aria-label="The FELEMAYE studio desk" style={{ display: "block", height: "auto" }}>
                    <rect width="1600" height="1000" fill="url(#g-desk)" /><rect width="1600" height="1000" filter="url(#dc-grain)" />
                    <AlvinCuttingMat />

                    {/* the drawing sheet */}
                    <g transform="translate(350 112) rotate(-.5)" filter="url(#dc-sh)">
                        <clipPath id="dc-clip"><rect width="860" height="760" /></clipPath>
                        <g clipPath="url(#dc-clip)"><Sheet hub={p.showHub} w={860} h={760} fs={1} nodes={nodes} hot={hot} setHot={setHot} sel={sel} setSel={setSel} t={t} coarse={coarse} logo={logo} /></g>
                    </g>
                    {/* left column */}
                    {itemLink(p.surfaceHref, "Surface Library: surface archive", -6, -4, 182, 234, <CompBook />, "translate(98 236) rotate(-4) scale(.92)")}
                    {itemLink(p.writingHref, "Perspectives: essays and records", -6, -4, 172, 236, <BlackBook />, "translate(170 456) rotate(3) scale(.88)")}
                    {itemLink(p.portalHref, "Client Suite: sign in to your project workspace", -4, -26, 232, 232, <Folders />, "translate(66 708) rotate(-2) scale(.92)")}
                    <g transform="translate(290 664) rotate(14) scale(.78)" onMouseEnter={() => setIpodHover(true)} onMouseLeave={() => setIpodHover(false)}><IPod st={st} onOpen={() => setOpen(true)} /></g>
                    {/* right column */}
                    {itemLink(p.aboutHref, "The studio: who is behind FELEMAYE", -12, -14, 254, 304, polaroid, "translate(1272 92) rotate(4)")}
                    {itemLink(p.practiceHref, "Practice: B2C and B2B breakdown", -6, -4, 204, 214, <Postit />, "translate(1296 428) rotate(-3)")}
                    {itemLink(p.calendarHref, "Book a studio call", -6, 0, 244, 232, <Calendar now={now} />, "translate(1262 650) rotate(1.5)")}
                    {/* bottom strip */}
                    {decor(<Pencils />, "translate(90 878) rotate(-1.5) scale(.92)")}
                    {itemLink(p.capabilitiesHref, "Capabilities matrix", -4, -4, 428, 52, <Ruler />, "translate(520 896) rotate(-1)")}
                    {decor(<Knife />, "translate(990 880) rotate(-3) scale(.9)")}
                    {decor(<Pens />, "translate(1312 886) rotate(-6) scale(.78)")}
                </svg>
            ) : (
                <div style={{ background: "radial-gradient(120% 70% at 50% 0%, #1d1812 0%, #0B0B0C 62%)", padding: "16px 12px 120px" }}>
                    <div style={{ boxShadow: "0 18px 40px rgba(0,0,0,.55)", border: "1px solid rgba(255,255,255,.08)", borderRadius: 14, overflow: "hidden", background: "#fbfbf6", position: "relative" }}>
                        <svg viewBox="0 0 560 640" width="100%" role="group" aria-label="Transdisciplinary ecosystem matrix" style={{ display: "block", height: "auto" }}>
                            <Sheet hub={p.showHub} w={560} h={640} fs={1.45} nodes={nodes} hot={hot} setHot={setHot} sel={sel} setSel={setSel} t={t} coarse={coarse} logo={logo} />
                        </svg>
                    </div>
                    <div aria-live="polite" style={{ background: "rgba(18,18,18,.6)", WebkitBackdropFilter: "blur(12px)", backdropFilter: "blur(12px)", color: "#EDE6D8", border: "1px solid rgba(255,255,255,.08)", borderRadius: 14, padding: "16px 18px", margin: "12px 0 0", minHeight: 96 }}>
                        {selNode ? (
                            <div>
                                <div className="mono" style={{ color: "#D4A373", opacity: 1 }}>{selNode.label}</div>
                                <p style={{ margin: "6px 0 8px", fontSize: 14, lineHeight: 1.6 }}>{selNode.desc}</p>
                                <div style={{ fontSize: 12, lineHeight: 1.7 }}>{rel.map((x) => <span key={x.other.id} style={{ display: "inline-block", marginRight: 12 }}><b>{x.other.code}</b> {x.l}</span>)}</div>
                                <a href={selNode.href} style={{ display: "inline-block", marginTop: 10, color: "#D4A373", fontFamily: MONO, fontSize: 11, letterSpacing: ".18em", textTransform: "uppercase", padding: "10px 0" }}>Open {selNode.label.toLowerCase()} ↗</a>
                            </div>
                        ) : <p style={{ margin: 0, fontSize: 14, lineHeight: 1.6, color: "#A39B8B" }}>Tap any discipline on the sheet to trace how it connects to the others.</p>}
                    </div>
                    <div style={{ display: "grid", gridTemplateColumns: W < 560 ? "repeat(2,minmax(0,1fr))" : "repeat(4,minmax(0,1fr))", gap: 10, marginTop: 24 }}>
                        {tiles.map((x) => x.href === "#ipod" ? (
                            <button key={x.title} className="tile" aria-label={x.title} onClick={() => setOpen(true)}>
                                <svg viewBox={x.vb} width="100%" style={{ display: "block", height: 150 }} aria-hidden="true" preserveAspectRatio="xMidYMid meet">{x.node}</svg>
                                {p.showCaptions && <span className="cap">{x.cap}</span>}
                            </button>
                        ) : (
                            <a key={x.title} className="tile" href={x.href} aria-label={x.title}>
                                <svg viewBox={x.vb} width="100%" style={{ display: "block", height: 150 }} aria-hidden="true" preserveAspectRatio="xMidYMid meet">{x.node}</svg>
                                {p.showCaptions && <span className="cap">{x.cap}</span>}
                            </a>
                        ))}
                    </div>
                </div>
            )}
            {!mobile && selNode && (
                <div aria-live="polite" style={{ position: "absolute", left: "23.5%", bottom: "24%", width: "22%", background: "#141416", color: "#EDE6D8", border: "1px solid #D4A373", padding: "10px 12px", fontSize: 12, lineHeight: 1.5, boxShadow: "0 6px 16px rgba(0,0,0,.25)", pointerEvents: "none" }}>
                    <div className="mono" style={{ opacity: 1 }}>{selNode.label}</div>
                    <div style={{ margin: "4px 0 6px" }}>{selNode.desc}</div>
                    <div style={{ fontFamily: MONO, fontSize: 10, opacity: 0.8 }}>{rel.map((x) => x.other.code + " " + x.l).join(" · ")}</div>
                </div>
            )}
            {!mobile && ipodHover && (
                <div role="tooltip" style={{ position: "absolute", left: "18.5%", top: "62%", transform: "translateX(-50%)", pointerEvents: "none", whiteSpace: "nowrap", background: "#141416", border: "1px solid #222226", color: "#EDE6D8", font: `10px ${MONO}`, letterSpacing: ".14em", textTransform: "uppercase", padding: "8px 12px", zIndex: 15 }}>See what's playing in the studio</div>
            )}
            <div aria-hidden={!open} style={{ position: mobile ? "fixed" : "absolute", ...(mobile ? { left: 0, right: 0, bottom: 0 } : { left: "19%", bottom: "3%", width: "min(380px, 40%)" }), transform: open ? "translateY(0)" : "translateY(14px)", opacity: open ? 1 : 0, pointerEvents: open ? "auto" : "none", transition: "opacity .25s, transform .25s", zIndex: 30, background: "rgba(18,18,18,.78)", WebkitBackdropFilter: "blur(12px)", backdropFilter: "blur(12px)", border: "1px solid rgba(255,255,255,.08)", borderRadius: 14, padding: 10, boxShadow: "0 18px 40px rgba(0,0,0,.55)" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "2px 4px 10px" }}>
                    <span style={{ font: `10px ${MONO}`, letterSpacing: ".22em", textTransform: "uppercase", color: "#D4A373" }}>The studio playlist</span>
                    <button aria-label="Close" onClick={() => setOpen(false)} style={{ background: "transparent", border: 0, color: "#A39B8B", cursor: "pointer", fontSize: 20, minWidth: 44, minHeight: 44 }}>×</button>
                </div>
                {p.playlist && spLoaded ? <iframe title="FELEMAYE studio playlist on Spotify" src={`https://open.spotify.com/embed/playlist/${spotifyId(p.playlist)}?utm_source=generator&theme=0`} width="100%" height="352" loading="lazy" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" style={{ border: 0, borderRadius: 8, display: "block" }} /> : <p style={{ margin: 8, color: "#A39B8B", fontSize: 13 }}>Add the Spotify playlist link in this component's sidebar.</p>}
            </div>
        </div>
    )
}

HomeDeskStudio.defaultProps = {
    portalHref: "/client-suite",
    practiceHref: "/practice",
    calendarHref: "mailto:felema@felemaye.com?subject=Studio%20call%20request",
    aboutHref: "/about",
    surfaceHref: "/surface-library",
    writingHref: "/perspectives",
    capabilitiesHref: "/capabilities",
    polaroidSrc: "",
    polaroidNote: "the courtyard at golden hour, Los Angeles",
    logoSrc: "",
    speed: 1,
    showHub: false,
    playlist: "",
    showCaptions: true,
    width: 1200,
}
addPropertyControls(HomeDeskStudio, {
    portalHref: { type: ControlType.String, title: "Client portal link" },
    practiceHref: { type: ControlType.String, title: "B2C / B2B link" },
    calendarHref: { type: ControlType.String, title: "Calendar link" },
    aboutHref: { type: ControlType.String, title: "Polaroid link" },
    surfaceHref: { type: ControlType.String, title: "Surface Library link" },
    writingHref: { type: ControlType.String, title: "Writing & media link" },
    capabilitiesHref: { type: ControlType.String, title: "Capabilities link" },
    polaroidSrc: { type: ControlType.Image, title: "Polaroid photo" },
    polaroidNote: { type: ControlType.String, title: "Polaroid note", displayTextArea: true },
    logoSrc: { type: ControlType.Image, title: "Logo mark (optional)" },
    showHub: { type: ControlType.Boolean, title: "Center hub", defaultValue: false },
    showCaptions: { type: ControlType.Boolean, title: "Mobile captions", defaultValue: true },
    playlist: { type: ControlType.String, title: "Spotify playlist", description: "Paste the playlist link or ID. Opens in the iPod drawer." },
    speed: { type: ControlType.Number, title: "Rotation speed", min: 0, max: 3, step: 0.1 },
})
